### Sources/Slotstream/CPUSlotWrite.swift
import MLX

/// Experimental shared-memory update using MLX's own CPU primitive. The graph
/// owns all inputs and cross-stream dependencies; there are no raw writes or
/// manual assumptions that an evaluated array has no surviving GPU reader.
/// A fresh Swift context preserves external aliases and permits donation only
/// when MLX proves exclusive storage ownership at evaluation.
package enum CPUSlotWrite {
    package static func apply(to destination: MLXArray, from source: MLXArray,
                              slots: [Int32]) throws -> MLXArray {
        guard destination.ndim >= 2, source.ndim == destination.ndim,
            destination.dtype == source.dtype,
            Array(destination.shape.dropFirst()) == Array(source.shape.dropFirst()),
            !slots.isEmpty, slots.count <= 32, source.dim(0) == slots.count,
            Set(slots).count == slots.count,
            slots.allSatisfy({ $0 >= 0 && Int($0) < destination.dim(0) }) else {
            throw ModelError("invalid CPU slot update geometry or destination rows")
        }
        let result = destination.reshaped(destination.shape, stream: .cpu)
        // The pinned generic CPU scatter visits each element individually.
        // Every validated batch has at most 32 runs; use the contiguous copy
        // primitive even when CLOCK returns many disjoint destination rows.
        // Donation and cross-stream dependencies still belong to MLX.
        guard let runs = SlotWriteRun.plan(slots, capacity: destination.dim(0), maximumRuns: 32) else {
            throw ModelError("invalid CPU slot copy plan")
        }
        for run in runs {
            result[run.destination, stream: .cpu] = source[run.source, stream: .cpu]
        }
        return result
    }
}

### Sources/Slotstream/EmbeddingRows.swift
import Foundation
import MLX

/// Optional bounded input-embedding cache. Calls are serialized; workers fill
/// private packed rows and never touch MLX or caches. The output head is separate.
package final class EmbeddingRows {
    package static let names = ["model.embed_tokens.weight", "model.embed_tokens.scales", "model.embed_tokens.biases"]
    package let refs: [TensorRef]
    private let handles: [TensorReadHandle]
    private let config: ModelConfig
    private let capacity: Int
    private let offsets: [Int]
    private let rowBytes: Int
    private var cache: [Int: Data] = [:]
    private var order: FIFOKeys
    package var readFault: ReadFault?
    package private(set) var uniqueRowHits = 0
    package private(set) var uniqueRowMisses = 0
    package var cachedRows: Int { cache.count }
    package var cachedPayloadBytes: Int { cache.count * rowBytes }
    package var residentPayloadBytes: Int { refs.reduce(0) { $0 + $1.byteCount } }

    package init(index: CheckpointIndex, capacity: Int = 8192) throws {
        guard (1 ... 8192).contains(capacity) else { throw ModelError("embedding row capacity must be 1...8192") }
        let cfg = index.config
        let refs = try Self.names.map { name -> TensorRef in
            guard let ref = index.tensors[name] else { throw ModelError("missing embedding tensor \(name)") }
            return ref
        }
        guard cfg.qBits == 4, cfg.qGroup == 64, cfg.hiddenSize == 2560,
              refs[0].shape == [cfg.vocabSize, cfg.hiddenSize / 8], refs[0].dtype == "U32",
              refs[1].shape == [cfg.vocabSize, cfg.hiddenSize / cfg.qGroup], refs[1].dtype == "BF16",
              refs[2].shape == refs[1].shape, refs[2].dtype == "BF16" else {
            throw ModelError("embedding row candidate requires the exact curated quantized geometry")
        }
        try ModelProcessGuard.acquire()
        self.refs = refs; self.handles = refs.map { index.readHandle(for: $0) }
        self.config = cfg; self.capacity = capacity; self.order = FIFOKeys(capacity: capacity)
        self.offsets = [0, refs[0].rowBytes, refs[0].rowBytes + refs[1].rowBytes]
        self.rowBytes = refs.reduce(0) { $0 + $1.rowBytes }
    }

    private final class Job {
        let id: Int
        var row: Data?
        init(_ id: Int) { self.id = id }
    }
    package func clear() { cache.removeAll(); order.removeAll() }

    package func gather(_ ids: [Int], shape: [Int]) throws -> MLXArray {
        var count = 1
        for dim in shape {
            let next = count.multipliedReportingOverflow(by: dim)
            guard (0 ... 4096).contains(dim), !next.overflow else { throw ModelError("invalid embedding row shape") }
            count = next.partialValue
        }
        guard count == ids.count, ids.count <= 4096,
              ids.allSatisfy({ $0 >= 0 && $0 < config.vocabSize }) else {
            throw ModelError("embedding row candidate requires valid IDs and at most 4096 positions")
        }
        if ids.isEmpty { return MLXArray.zeros(shape + [config.hiddenSize], dtype: .bfloat16) }
        var seen = Set<Int>(), available: [Int: Data] = [:], jobs: [Job] = []
        var hits = 0
        for id in ids where seen.insert(id).inserted {
            if let row = cache[id] { available[id] = row; hits += 1 }
            else { jobs.append(Job(id)) }
        }
        let failure = JoinedReadFailure()
        let workers = min(32, jobs.count)
        if workers > 0 {
            DispatchQueue.concurrentPerform(iterations: workers) { worker in
                for i in stride(from: worker, to: jobs.count, by: workers) {
                    let job = jobs[i]
                    do {
                        var row = Data(count: rowBytes)
                        try row.withUnsafeMutableBytes { bytes in
                            for p in refs.indices {
                                try readFault?.beforeRead()
                                try handles[p].readChecked(into: bytes.baseAddress! + offsets[p],
                                    offset: job.id * refs[p].rowBytes, count: refs[p].rowBytes)
                            }
                        }
                        job.row = row
                    } catch { failure.record(error) }
                }
            }
        }
        // Join before any insertion/eviction. A failed piece or batch cannot
        // publish partial rows or change previously valid cache ownership.
        try failure.finish()
        for job in jobs {
            guard let row = job.row else { throw ModelError("embedding row job completed without bytes") }
            available[job.id] = row
        }
        for job in jobs {
            if cache.count == capacity, let old = order.popFirst() { cache.removeValue(forKey: Int(old)) }
            cache[job.id] = available[job.id]!
            order.append(Int64(job.id))
        }
        uniqueRowHits += hits; uniqueRowMisses += jobs.count
        var pieces: [MLXArray] = []
        for p in refs.indices {
            let stride = refs[p].rowBytes
            var data = Data(count: ids.count * stride)
            data.withUnsafeMutableBytes { output in
                for (i, id) in ids.enumerated() {
                    available[id]!.withUnsafeBytes { row in
                        memcpy(output.baseAddress! + i * stride, row.baseAddress! + offsets[p], stride)
                    }
                }
            }
            // MLX dequantization requires a matrix even for a scalar ID.
            // Preserve the caller's shape only after independent row math.
            pieces.append(MLXArray(data, [ids.count, refs[p].shape[1]], dtype: p == 0 ? .uint32 : .bfloat16))
        }
        return dequantized(pieces[0], scales: pieces[1], biases: pieces[2],
            groupSize: config.qGroup, bits: config.qBits).reshaped(shape + [config.hiddenSize])
    }
}

### Sources/Slotstream/ExactRead.swift
import Darwin
import Foundation

public enum CheckpointReadError: Error, CustomStringConvertible {
    case invalidRange, cancelled, unexpectedEOF(offset: Int), system(offset: Int, code: Int32)
    case invalidProgress
    public var description: String {
        switch self {
        case .invalidRange: return "checkpoint read range is outside its tensor or overflows"
        case .cancelled: return "checkpoint read cancelled before completion"
        case let .unexpectedEOF(offset): return "checkpoint ended before the requested bytes at offset \(offset)"
        case let .system(offset, code): return "checkpoint read at offset \(offset) failed: \(String(cString: strerror(code)))"
        case .invalidProgress: return "checkpoint reader returned more bytes than requested"
        }
    }
}

/// A bounded syscall seam. A completed transfer is the only publishable
/// outcome; callers must discard the partially written destination on error.
package enum ExactRead {
    package static func tensorOffset(base: Int, length: Int, offset: Int, count: Int) throws -> Int {
        guard base >= 0, length >= 0, offset >= 0, count >= 0,
            offset <= length, count <= length - offset,
            !base.addingReportingOverflow(offset).overflow else { throw CheckpointReadError.invalidRange }
        let absolute = base + offset
        guard !absolute.addingReportingOverflow(count).overflow else { throw CheckpointReadError.invalidRange }
        return absolute
    }
    package struct Outcome {
        package let count: Int
        package let error: Int32
        package init(count: Int, error: Int32 = 0) { self.count = count; self.error = error }
    }
    package static func transfer(into destination: UnsafeMutableRawPointer, offset: Int, count: Int,
        shouldContinue: () -> Bool = { true },
        read: (UnsafeMutableRawPointer, Int, Int) -> Outcome) throws {
        guard offset >= 0, count >= 0, !offset.addingReportingOverflow(count).overflow else {
            throw CheckpointReadError.invalidRange
        }
        var done = 0
        while done < count {
            guard shouldContinue() else { throw CheckpointReadError.cancelled }
            let next = read(destination + done, count - done, offset + done)
            if next.count < 0 {
                if next.error == EINTR { continue }
                throw CheckpointReadError.system(offset: offset + done, code: next.error)
            }
            guard next.count > 0 else { throw CheckpointReadError.unexpectedEOF(offset: offset + done) }
            guard next.count <= count - done else { throw CheckpointReadError.invalidProgress }
            done += next.count
        }
    }
}

/// concurrentPerform joins every worker before this result is inspected.
/// Successful jobs need no shared lock; errors are retained once and the
/// entire partially filled destination is discarded after the join.
package final class JoinedReadFailure {
    private let lock = NSLock()
    private var first: Error?
    package func record(_ error: Error) {
        lock.lock(); defer { lock.unlock() }
        if first == nil { first = error }
    }
    package func finish() throws {
        lock.lock(); defer { lock.unlock() }
        if let first { throw first }
    }
}

/// One-shot bounded diagnostic seam. It never modifies checkpoint files.
/// Install/remove only between reads; claims can arrive on several I/O lanes.
package final class ReadFault {
    private let lock = NSLock()
    private var remaining: Int
    private let error: CheckpointReadError
    package init(afterJobs: Int, error: CheckpointReadError = .system(offset: 0, code: EIO)) {
        precondition(afterJobs >= 0)
        remaining = afterJobs; self.error = error
    }
    package func beforeRead() throws {
        lock.lock(); defer { lock.unlock() }
        if remaining == 0 { remaining = -1; throw error }
        if remaining > 0 { remaining -= 1 }
    }
    package var hasFired: Bool {
        lock.lock(); defer { lock.unlock() }
        return remaining < 0
    }
}

### Sources/Slotstream/RouterTrace.swift
// Router traces, so the cache simulator can finally be fed real data.
//
// M1 — the expert-locality study — has been open since the beginning: the
// simulator (`Tools/cachesim.py`) and the collector for the Python reference
// (`Tools/trace_routers.py`) were both built in 2026-08, but no trace was ever
// taken from a bounded forward pass, because at the time no bounded forward
// pass existed. It does now, and the decode split says 44% of decode time at a
// small cache is reading expert records, so which records the cache keeps is
// the question that decides that number.
//
// `SLOTSTREAM_ROUTER_TRACE=<path>` records every routing decision the model
// makes and writes it on exit. The format is a flat stream a reader
// reassembles: per MoE call, `layer`, `tokens`, `topK` as little-endian int32,
// then `tokens * topK` int16 expert ids. Layers are visited in order within a
// pass, so a reader groups by pass without needing a pass id.
//
// The trace is off unless the variable is set, and reading it costs one static
// Bool per MoE call.

import Foundation

public enum RouterTrace {
    public static let path: String? =
        ProcessInfo.processInfo.environment["SLOTSTREAM_ROUTER_TRACE"]
    public static let on: Bool = path != nil

    private static let lock = NSLock()
    private static var buffer = Data()
    private static var calls = 0
    private static var uses = 0

    public static func record(layer: Int, tokens: Int, topK: Int, ids: [Int32]) {
        guard on else { return }
        lock.lock()
        defer { lock.unlock() }
        var header = [Int32(layer), Int32(tokens), Int32(topK)]
        header.withUnsafeBytes { buffer.append(contentsOf: $0) }
        var small = [Int16](repeating: 0, count: ids.count)
        for (i, v) in ids.enumerated() { small[i] = Int16(truncatingIfNeeded: v) }
        small.withUnsafeBytes { buffer.append(contentsOf: $0) }
        calls += 1
        uses += ids.count
    }

    /// Write the trace out. Called once, at the end of a generation.
    @discardableResult
    public static func flush() -> String? {
        guard on, let path else { return nil }
        lock.lock()
        defer { lock.unlock() }
        guard !buffer.isEmpty else { return nil }
        try? buffer.write(to: URL(fileURLWithPath: path))
        let line = "router trace: \(calls) MoE calls, \(uses) expert-uses -> \(path)"
        buffer = Data()
        calls = 0
        uses = 0
        return line
    }
}

### Tools/cache_policy_confirmation.py
#!/usr/bin/env python3
"""Fresh trace screen for the floor-only layer-local replacement hypothesis.

No cache policy is enabled in inference. Replayed CLOCK must first reproduce
the real process's exact physical decode-record count, including prefill warmth.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import struct
from cache_policy_probe import Cache, RECORD_BYTES
from prefill_bench import preflight, run_child, model_identity, digest
from serve_bench import verified_build

PROMPTS = {
    'compiler': 'Write a detailed explanation of how a compiler detects syntax errors and reports line numbers.',
    'containers': 'Explain how a queue differs from a stack. Illustrate both with a short sequence of insertions and removals.',
}


def parse_trace(raw):
    if len(raw) > 1_000_000:
        raise ValueError('trace exceeds the fixed bounded request')
    calls = []
    offset = 0
    while offset < len(raw):
        if len(raw) - offset < 12:
            raise ValueError('incomplete trace header')
        layer, tokens, top_k = struct.unpack_from('<iii', raw, offset)
        offset += 12
        if layer != len(calls) % 48 or not 1 <= tokens <= 256 or top_k != 10:
            raise ValueError('unexpected layer or routing shape')
        count = tokens * top_k
        if len(raw) - offset < count * 2:
            raise ValueError('incomplete trace payload')
        ids = struct.unpack_from('<' + 'h' * count, raw, offset)
        offset += count * 2
        if min(ids) < 0 or max(ids) >= 512:
            raise ValueError('invalid expert ID')
        calls.append((layer, tokens, ids))
    if len(calls) < 96 or len(calls) % 48 or any(tokens != 1 for _, tokens, _ in calls[48:]):
        raise ValueError('expected one bounded prefill followed by complete decode passes')
    return calls


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--binary', type=Path, required=True)
    parser.add_argument('--model', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    a = parser.parse_args()
    build = verified_build(a.binary)
    a.out = a.out.resolve()
    a.out.mkdir(exist_ok=False, parents=True)
    sources = [Path(__file__), Path(__file__).with_name('cache_policy_probe.py'),
               Path(__file__).with_name('prefill_bench.py'), Path(__file__).with_name('serve_bench.py')]
    manifest = {'classification': 'fresh reference routing and offline floor-only cache hypothesis; not latency evidence',
                'build': build, 'model': model_identity(a.model.resolve()), 'prompts': PROMPTS,
                'slots': 640, 'memory_gb': 8.1, 'max_output_tokens': 64,
                'proposal': 'At exactly 640 slots, prefer empty then unpinned current-layer records; use CLOCK at every other capacity. No frequency counters or future routing inputs.',
                'gate': 'Both fresh prompts must produce at least sixteen decode passes, exact reference replay record counts and at least five percent fewer candidate physical decode records. No replacements or policy changes.'}
    manifest['sources'] = {p.name: digest(p) for p in sources}
    for source in sources:
        (a.out/source.name).write_bytes(source.read_bytes())
    (a.out/'manifest.json').write_text(json.dumps(manifest, indent=2)+'\n')
    rows = []
    for name, prompt in PROMPTS.items():
        cell = a.out/name
        cell.mkdir()
        (cell/'prompt.txt').write_text(prompt+'\n')
        command = [build['binary'], 'run', '--model', str(a.model.resolve()), '--memory-gb', '8.1',
                   '--mtp', 'off', '--prompt-file', str(cell/'prompt.txt'), '--greedy', '--seed', '7',
                   '--max-tokens', '64', '--stats-json', str(cell/'stats.json'), '--sample-footprint']
        env = {k: v for k, v in os.environ.items() if not k.startswith(('SLOTSTREAM_', 'SS_DEBUG'))}
        env |= {'SLOTSTREAM_ROUTER_TRACE': str(cell/'trace.bin'), 'SLOTSTREAM_PREFILL_CHUNK': '256',
                'SLOTSTREAM_PREFIX_CACHE': '0', 'SLOTSTREAM_OPT_COMPACT_STATE': '1', 'SLOTSTREAM_OPT_FINAL_FORWARD': '1'}
        row = {'name': name, 'command': command, 'environment': {k: v for k, v in env.items() if k.startswith('SLOTSTREAM_')}}
        row['preflight'] = preflight(11.1)
        row['exit_code'] = run_child(command, env, cell, 180)
        if row['exit_code']:
            (cell/'result.json').write_text(json.dumps(row, indent=2)+'\n')
            raise RuntimeError('reference trace generation failed')
        payload = json.loads((cell/'stats.json').read_text())
        calls = parse_trace((cell/'trace.bin').read_bytes())
        row['trace_sha256'] = digest(cell/'trace.bin')
        row['decode_passes'] = len(calls) // 48 - 1
        row['model_decode_records'] = payload['stats']['decodeRecords']
        for arm in ['reference', 'candidate']:
            cache = Cache(640, False, layer_local=arm == 'candidate')
            records = [cache.request(layer, ids) for layer, _, ids in calls]
            row[arm] = {'prefill_records': sum(records[:48]), 'decode_records': sum(records[48:]),
                        'by_call': records}
        row['reference_exact'] = row['reference']['decode_records'] == row['model_decode_records']
        row['record_reduction'] = 1 - row['candidate']['decode_records'] / row['reference']['decode_records']
        row['passed'] = row['decode_passes'] >= 16 and row['reference_exact'] and row['record_reduction'] >= .05
        (cell/'result.json').write_text(json.dumps(row, indent=2)+'\n')
        rows.append(row)
        print({k: row[k] for k in ['name', 'decode_passes', 'model_decode_records', 'reference_exact', 'record_reduction', 'passed']}, flush=True)
    passed = all(row['passed'] for row in rows)
    (a.out/'completion.json').write_text(json.dumps({'passed': passed, 'cells': len(rows)})+'\n')
    return 0 if passed else 1


if __name__ == '__main__':
    raise SystemExit(main())

### Tools/cachesim.py
"""M1: expert slot-cache simulator.

Replays real router traces against cache policies and sizes to produce the
h(size) curves the whole tiering rests on. No model needed.

Key modelling detail: the cache is GLOBAL across layers, keyed by
(layer, expert) -> 24,576 distinct records of 2.7648 MB each.

Usage:
  python cachesim.py bench/traces/*.npz
"""
import sys, json, glob
import numpy as np
from collections import OrderedDict, defaultdict

REC_MB = 2.7648
N_LAYERS, N_EXPERTS = 48, 512
TOTAL_RECORDS = N_LAYERS * N_EXPERTS


class LRU:
    name = "LRU"

    def __init__(self, cap):
        self.cap = cap
        self.d = OrderedDict()

    def access(self, key):
        if key in self.d:
            self.d.move_to_end(key)
            return True
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)
        self.d[key] = 1
        return False


class LFUDecay:
    """CLOCK-ish frequency cache: evict lowest freq, halve counters periodically."""
    name = "LFU-decay"

    def __init__(self, cap, decay_every=20000):
        self.cap = cap
        self.freq = {}
        self.n = 0
        self.decay_every = decay_every

    def access(self, key):
        self.n += 1
        if self.n % self.decay_every == 0:
            for k in self.freq:
                self.freq[k] >>= 1
        if key in self.freq:
            self.freq[key] += 1
            return True
        if len(self.freq) >= self.cap:
            victim = min(self.freq, key=self.freq.get)
            del self.freq[victim]
        self.freq[key] = 1
        return False


class Belady:
    """Offline optimal (upper bound). Only for small traces."""
    name = "OPT(bound)"

    def __init__(self, cap, seq):
        self.cap = cap
        self.next = defaultdict(list)
        for i, k in enumerate(seq):
            self.next[k].append(i)
        self.pos = defaultdict(int)
        self.cache = set()
        self.i = -1
        self.seq = seq

    def access(self, key):
        self.i += 1
        self.pos[key] += 1
        if key in self.cache:
            return True
        if len(self.cache) >= self.cap:
            # evict the one used farthest in the future
            worst, worst_at = None, -1
            for c in self.cache:
                nxt = self.next[c]
                p = self.pos[c]
                at = nxt[p] if p < len(nxt) else 10**9
                if at > worst_at:
                    worst, worst_at = c, at
            self.cache.discard(worst)
        self.cache.add(key)
        return False


def trace_to_keys(arr):
    """(steps, layers, topk) -> flat sequence of (layer*512+expert) keys."""
    steps, layers, topk = arr.shape
    lay = np.arange(layers, dtype=np.int32)[None, :, None]
    keys = lay * N_EXPERTS + arr.astype(np.int32)
    return keys.reshape(-1)


def hot_set_pinned(keys, cap, hot_frac=0.5):
    """Pin the globally hottest `hot_frac*cap` records, LRU the rest."""
    counts = np.bincount(keys, minlength=TOTAL_RECORDS)
    n_hot = int(cap * hot_frac)
    hot = set(np.argsort(-counts)[:n_hot].tolist())
    lru = LRU(cap - n_hot)
    hits = 0
    for k in keys:
        if k in hot:
            hits += 1
        elif lru.access(k):
            hits += 1
    return hits / len(keys)


def simulate(keys, cap, policy_cls):
    p = policy_cls(cap)
    hits = 0
    for k in keys:
        if p.access(int(k)):
            hits += 1
    return hits / len(keys)


def analyze(name, arr, caps_gb):
    keys = trace_to_keys(arr)
    steps = arr.shape[0]
    uniq = len(np.unique(keys))
    counts = np.bincount(keys, minlength=TOTAL_RECORDS)
    nz = counts[counts > 0]
    top10 = np.sort(counts)[::-1][: int(TOTAL_RECORDS * 0.1)].sum() / counts.sum()

    print(f"\n### {name}: {steps} steps, {len(keys):,} expert-uses")
    print(f"    distinct records touched: {uniq:,} / {TOTAL_RECORDS:,} "
          f"({100*uniq/TOTAL_RECORDS:.1f}%)")
    print(f"    top-10% of records serve {100*top10:.1f}% of accesses "
          f"(concentration)")
    print(f"    working set if fully cached: {uniq*REC_MB/1024:.1f} GB")

    print(f"    {'exp/layer':>9} {'cache GB':>9} {'slots':>7} {'LRU':>8} {'LFU':>8} {'hot+LRU':>8}"
          f" {'miss MB/tok':>12} {'IO ms/tok@6GB/s':>16}")
    rows = []
    for gb in caps_gb:
        cap = int(gb * 1024 / REC_MB)
        if cap < 1:
            continue
        h_lru = simulate(keys, cap, LRU)
        h_lfu = simulate(keys, cap, LFUDecay)
        h_hot = hot_set_pinned(keys, cap)
        best = max(h_lru, h_lfu, h_hot)
        per_tok = arr.shape[1] * arr.shape[2]  # layers*topk expert-uses per token
        miss_mb = per_tok * (1 - best) * REC_MB
        io_ms = miss_mb / 6000 * 1000
        print(f"    {cap/N_LAYERS:9.1f} {gb:9.1f} {cap:7d} {h_lru:8.3f} {h_lfu:8.3f} {h_hot:8.3f}"
              f" {miss_mb:12.1f} {io_ms:16.1f}")
        rows.append(dict(gb=gb, slots=cap, lru=h_lru, lfu=h_lfu, hot=h_hot,
                         miss_mb=miss_mb, io_ms=io_ms))
    return rows


if __name__ == "__main__":
    files = sys.argv[1:] or sorted(glob.glob("bench/traces/*.npz"))
    if not files:
        print("no traces given"); sys.exit(1)
    caps = [0.5, 1, 2, 5.5, 10.5, 16, 27, 36, 56, 68]
    out = {}
    for f in files:
        z = np.load(f)
        for k in z.files:
            if k == "meta":
                continue
            arr = z[k]
            if arr.ndim != 3:
                continue
            out[f"{f}:{k}"] = analyze(f"{f.split('/')[-1]}:{k}", arr, caps)
    with open("bench/locality/summary.json", "w") as fh:
        json.dump(out, fh, indent=2)
    print("\nwrote bench/locality/summary.json")

### Tools/claims_gate.py
#!/usr/bin/env python3
"""Every public number has a claim record; every claim's needle is on its surfaces.

Reads db/records/claims/*.md. A `current` claim's `needle` must appear
verbatim in every file listed in `surfaces`; a `withdrawn` claim's needle
must appear in none of them. The gate exists because numbers drifted between
README, docs, and llms.txt for three releases before anyone noticed; a
measurement that changes now fails CI until its claim and its surfaces move
together. Matching ignores line wrapping: runs of whitespace on both sides
collapse to one space, so a needle may span a wrapped line. Standard library
only.
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLAIMS = os.path.join(ROOT, 'db', 'records', 'claims')

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from projections import read_record  # noqa: E402


def squash(text):
    return ' '.join(text.split())


def main():
    if not os.path.isdir(CLAIMS):
        print('no claims folder at %s' % CLAIMS, file=sys.stderr)
        return 1
    failures, checked = [], 0
    for name in sorted(os.listdir(CLAIMS)):
        if not name.endswith('.md') or name == 'index.md':
            continue
        fm, _ = read_record(os.path.join(CLAIMS, name))
        needle = fm.get('needle', '')
        status = fm.get('status', '')
        surfaces = [s.strip() for s in fm.get('surfaces', '').split(',') if s.strip()]
        if not needle or not surfaces or status not in ('current', 'withdrawn'):
            failures.append('%s: needs needle, surfaces, and a current/withdrawn status' % name)
            continue
        for surface in surfaces:
            path = os.path.join(ROOT, surface)
            if not os.path.isfile(path):
                failures.append('%s: surface %s does not exist' % (name, surface))
                continue
            present = squash(needle) in squash(open(path, encoding='utf-8').read())
            checked += 1
            if status == 'current' and not present:
                failures.append('%s: current claim needle %r missing from %s' % (name, needle, surface))
            if status == 'withdrawn' and present:
                failures.append('%s: withdrawn claim needle %r still on %s' % (name, needle, surface))
    for f in failures:
        print('CLAIM FAIL ' + f, file=sys.stderr)
    print('claims gate: %d needle checks, %d failures' % (checked, len(failures)))
    return 1 if failures else 0


if __name__ == '__main__':
    sys.exit(main())

### Tools/context_acceptance.py
#!/usr/bin/env python3
"""Model-free context acceptance and a portable, separately bound hardware campaign.

proxy runs only inert process/transport fixtures and isolated Swift policy.
prepare snapshots this working source and all test drivers without a model.
bind performs metadata/plan-only checks on the future target, never inference.
run-capacity is the explicit native resource/capacity operation on that target.
"""
import argparse
import ast
import hashlib
import io
import json
import os
from pathlib import Path
import platform
import re
import subprocess
import sys
import tarfile

import build_identity
import context_proxy
import context_qualification as capacity
import context_resource_gates as resources

ROOT = Path(__file__).resolve().parent.parent
CATALOG = ROOT / 'Tools/fixtures/context-acceptance-v1.json'
SUITES = ['context_contracts_test', 'context_qualification_checks', 'context_acceptance_test',
          'api_generation_test', 'e2e_release_test', 'consumer_smoke_test',
          'vision_capacity_gate_test', 'process_cleanup_checks', 'build_identity_test']


def write(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')


def source_files():
    # Keep executable closure in the snapshot, including native headers and
    # image/parity fixtures, but never compiler caches, weights or local venvs.
    files = set(build_identity.source_files(ROOT))
    for folder in ('Tools', 'bench/parity31', '.github/workflows', '.githooks'):
        for p in (ROOT / folder).rglob('*'):
            if p.is_symlink():
                raise ValueError('handoff requires explicit symlink dependencies: ' + str(p.relative_to(ROOT)))
            if p.is_file() and '__pycache__' not in p.parts and p.suffix != '.pyc' and 'lib' not in p.relative_to(ROOT).parts:
                files.add(p)
    files.add(CATALOG)
    for name in ('install.sh', 'Tools/context_proxy.swift', 'db/records/plan/configurable-context-window-2026-09-06.md'):
        files.add(ROOT / name)
    return sorted(files)


def source_identity():
    return {str(p.relative_to(ROOT)): capacity.digest(p) for p in source_files()}


def proxy_identity():
    """Hash actual policy and recursively imported local fixture dependencies."""
    result = context_proxy.selected_sources()
    pending = [ROOT / 'Tools' / (name + '.py') for name in SUITES + ['context_acceptance', 'context_proxy']]
    seen = set()
    while pending:
        path = pending.pop()
        if path in seen:
            continue
        seen.add(path)
        result[str(path.relative_to(ROOT))] = capacity.digest(path)
        for node in ast.walk(ast.parse(path.read_text())):
            modules = [alias.name for alias in node.names] if isinstance(node, ast.Import) else (
                [node.module] if isinstance(node, ast.ImportFrom) and node.module else [])
            for module in modules:
                local = ROOT / 'Tools' / (module.split('.')[0] + '.py')
                if local.is_file(): pending.append(local)
    for name in ('api_robustness.sh', 'e2e_release.sh', 'consumer_smoke.sh'):
        result['Tools/' + name] = capacity.digest(ROOT / 'Tools' / name)
    result[str(CATALOG.relative_to(ROOT))] = capacity.digest(CATALOG)
    return dict(sorted(result.items()))


def catalog():
    value = json.loads(CATALOG.read_text())
    ids = [row['id'] for row in value['cases']]
    if value.get('schema') != 1 or ids != [f'C{n:02}' for n in range(1, 23)]:
        raise ValueError('acceptance catalogue must preserve every C01-C22 case exactly once')
    allowed = set(SUITES) | {'swift_policy'}
    for row in value['cases']:
        if not row['deferred_native'] or not set(row['proxy_suites']) <= allowed:
            raise ValueError('missing native scope or unknown proxy suite for ' + row['id'])
    return value


def proxy(out):
    out.mkdir(parents=True, exist_ok=False)
    plan = catalog()
    before = proxy_identity()
    report = {'kind': 'context-software-proxy', 'passed': False, 'hardware_qualified': False,
              'release_qualified': False, 'model_loaded': False, 'suites': [], 'source_sha256': before}
    try:
        for name in SUITES:
            cell = out / name
            cell.mkdir()
            command = [sys.executable, '-m', 'unittest', 'discover', '-s', 'Tools', '-p', name + '.py', '-v']
            env = {k: v for k, v in os.environ.items() if not k.startswith('SLOTSTREAM_')}
            result = subprocess.run(command, cwd=ROOT, env=env, capture_output=True, text=True, timeout=180)
            (cell / 'stdout.txt').write_text(result.stdout)
            (cell / 'stderr.txt').write_text(result.stderr)
            count = re.search(r'^Ran (\d+) tests? in ', result.stderr, re.M)
            ok = result.returncode == 0 and count is not None and int(count.group(1)) > 0 and '\nOK' in result.stderr
            row = {'name': name, 'passed': ok, 'exit_code': result.returncode,
                   'tests': int(count.group(1)) if count else 0}
            report['suites'].append(row)
            print(json.dumps(row), flush=True)
        swift = context_proxy.run(out / 'swift_policy')
        report['suites'].append({'name': 'swift_policy', 'passed': swift['passed'],
                                 'contracts': swift.get('contracts'), 'failures': swift['failures']})
        results = {row['name']: row['passed'] for row in report['suites']}
        report['cases'] = [{**row, 'proxy_passed': bool(row['proxy_suites']) and all(results[name] for name in row['proxy_suites']),
                            'native_status': 'deferred_by_user'} for row in plan['cases']]
        if before != proxy_identity():
            raise ValueError('source or driver changed during acceptance; rerun the affected software checks')
        report['passed'] = all(results.values())
    except Exception as error:
        report['error'] = f'{type(error).__name__}: {error}'
    write(out / 'report.json', report)
    return report


def prepare(out):
    out.mkdir(parents=True, exist_ok=False)
    plan = catalog()
    sources = source_identity()
    with tarfile.open(out / 'source.tar.gz', 'w:gz') as tar:
        for name, digest in sources.items():
            p = ROOT / name
            data = p.read_bytes()
            if hashlib.sha256(data).hexdigest() != digest:
                raise ValueError('source changed during handoff capture')
            info = tar.gettarinfo(str(p), arcname=name)
            info.uid = info.gid = 0
            info.uname = info.gname = ''
            tar.addfile(info, io.BytesIO(data))
    if sources != source_identity():
        raise ValueError('source changed during handoff capture')
    result = {'schema': 1, 'kind': 'context-target-handoff', 'state': 'prepared_unrun',
              'source_sha256': sources, 'source_archive_sha256': capacity.digest(out / 'source.tar.gz'),
              'build_source': {str(p.relative_to(ROOT)): capacity.digest(p) for p in build_identity.source_files(ROOT)},
              'acceptance': plan, 'hardware_qualified': False, 'release_qualified': False}
    write(out / 'handoff.json', result)
    return result


def check_handoff(handoff):
    if handoff.get('schema') != 1 or handoff.get('kind') != 'context-target-handoff':
        raise ValueError('unknown handoff')
    if handoff['source_sha256'] != source_identity() or handoff['acceptance'] != catalog():
        raise ValueError('working source differs from handoff; prepare a new identified successor')
    expected = {str(p.relative_to(ROOT)): capacity.digest(p) for p in build_identity.source_files(ROOT)}
    if handoff.get('build_source') != expected:
        raise ValueError('build source differs from the captured handoff')


def bind(handoff, binary, model, out):
    check_handoff(handoff)
    binary, model = binary.resolve(), model.resolve()
    identity = json.loads((binary.parent / 'build-identity.json').read_text())
    if identity['source'] != handoff['build_source']:
        raise ValueError('candidate was not built from the handoff source; old candidates cannot certify new code')
    for file, key in [(binary, 'binary_sha256'), (binary.parent / 'mlx.metallib', 'metallib_sha256'),
                      (binary.parent / 'build-source.tar.gz', 'source_archive_sha256')]:
        if capacity.digest(file) != identity[key]:
            raise ValueError('candidate bytes differ from build identity: ' + key)
    # Check every archived source byte, not only the manifest assertion.
    with tarfile.open(binary.parent / 'build-source.tar.gz', 'r:gz') as tar:
        members = tar.getmembers()
        if len(members) != len(identity['source']) or {m.name for m in members} != set(identity['source']):
            raise ValueError('build archive source closure differs from the candidate identity')
        for member in members:
            if not member.isfile() or hashlib.sha256(tar.extractfile(member).read()).hexdigest() != identity['source'][member.name]:
                raise ValueError('build archive contains invalid source bytes')
        pinned = tar.extractfile('Sources/Slotstream/PinnedModel.swift').read()
    revision = re.search(rb'public static let revision = "([a-f0-9]+)"', pinned).group(1).decode()
    observed = capacity.observed_model(model)
    out.mkdir(parents=True, exist_ok=False)
    profiles = []
    for item in handoff['acceptance']['capacity_profiles']:
        protocol = {**{key: identity[key] for key in ('binary_sha256', 'metallib_sha256', 'source_archive_sha256')},
            'schema': 1, 'kind': 'configurable-context-retained-capacity' if item['retained'] else 'configurable-context-capacity',
            'binary': str(binary), 'model_dir': str(model), 'model_revision': revision,
            'model_manifest_sha256': hashlib.sha256(pinned).hexdigest(), 'model_identity': observed,
            'memory_gb': item['memory_gb'], 'prompt_tokens': [n - 16 for n in item['totals']],
            'reply_tokens': 16, 'wall_seconds': item['wall_seconds'], 'mtp': 'off', 'vision': 'off',
            'prefix_cache': item['retained'], 'max_prefill_wait_minutes': 0,
            'driver_sources': {name: capacity.digest(ROOT / name) for name in capacity.DRIVERS}}
        if item['retained']:
            protocol.update(warm_conversations=4, warm_tokens=item['warm_tokens'])
        env = {k: v for k, v in os.environ.items() if not k.startswith('SLOTSTREAM_')}
        env['SLOTSTREAM_PREFIX_CACHE'] = '1' if item['retained'] else '0'
        # Uses the actual planner and pinned headers only; never constructs Engine.
        args = [str(binary), 'context-check', '--tokens', str(protocol['prompt_tokens'][-1]), '--reply-tokens', '16',
                '--memory-gb', str(item['memory_gb']), '--mtp', 'off', '--vision', 'off', '--max-prefill-wait', '0',
                '--model', str(model), '--plan-only']
        if item['retained']:
            args += ['--warm-conversations', '4', '--warm-tokens', str(item['warm_tokens'])]
        planned = subprocess.run(args, env=env, capture_output=True, text=True, timeout=120)
        (out / (item['name'] + '.plan.stdout.json')).write_text(planned.stdout)
        (out / (item['name'] + '.plan.stderr.txt')).write_text(planned.stderr)
        value = json.loads(planned.stdout)
        if (planned.returncode or value.get('kind') != 'unqualified-context-plan' or value.get('qualified') is not False
                or 'fits' in value or value.get('model_revision') != revision
                or value.get('plan', {}).get('max_context_tokens') != item['totals'][-1]
                or value.get('warm_conversations') != (4 if item['retained'] else 0)
                or (item['retained'] and value.get('warm_tokens') != item['warm_tokens'])
                or value.get('plan', {}).get('runtime_prefix_cache_enabled') is not item['retained']):
            raise ValueError('plan-only did not resolve the exact requested candidate window')
        protocol['optimizations'] = value['optimizations']
        capacity.validate(protocol)
        write(out / (item['name'] + '.json'), protocol)
        profiles.append({'name': item['name'], 'protocol': protocol})
    result = {'schema': 1, 'kind': 'context-bound-campaign', 'state': 'bound_unrun',
              'handoff': handoff, 'profiles': profiles, 'hardware_qualified': False, 'release_qualified': False}
    write(out / 'binding.json', result)
    return result


def validate_binding(binding):
    if binding.get('schema') != 1 or binding.get('kind') != 'context-bound-campaign':
        raise ValueError('unknown bound campaign')
    check_handoff(binding['handoff'])
    expected = binding['handoff']['acceptance']['capacity_profiles']
    profiles = binding['profiles']
    if len(profiles) != len(expected):
        raise ValueError('capacity campaign cannot omit a profile')
    common = ('binary', 'binary_sha256', 'metallib_sha256', 'source_archive_sha256',
              'model_dir', 'model_revision', 'model_manifest_sha256', 'model_identity', 'driver_sources')
    first = profiles[0]['protocol']
    identity = json.loads((Path(first['binary']).parent / 'build-identity.json').read_text())
    if identity['source'] != binding['handoff']['build_source']:
        raise ValueError('bound candidate differs from the handoff source')
    for row, frozen in zip(profiles, expected):
        p = row['protocol']
        if (row['name'] != frozen['name'] or p['memory_gb'] != frozen['memory_gb']
                or [n + p['reply_tokens'] for n in p['prompt_tokens']] != frozen['totals']
                or p['reply_tokens'] != 16 or p['wall_seconds'] != frozen['wall_seconds']
                or p['prefix_cache'] is not frozen['retained']
                or p.get('warm_tokens') != frozen.get('warm_tokens')
                or any(p[key] != first[key] for key in common)):
            raise ValueError('capacity profile differs from frozen campaign')
        capacity.validate(p)
    return profiles


def run_capacity(binding, out, *, execute_on_target=False):
    if not execute_on_target or platform.system() != 'Darwin':
        raise ValueError('native campaign requires --execute-on-target on the intended Mac; proxy/prepare never launch it')
    profiles = validate_binding(binding)
    out.mkdir(parents=True, exist_ok=False)
    result = {'kind': 'context-native-capacity-campaign', 'passed': False, 'hardware_qualified': False,
              'release_qualified': False, 'profiles': []}
    try:
        p = profiles[0]['protocol']
        result['resources'] = resources.run(Path(p['binary']), Path(p['model_dir']),
            ROOT / 'Tools/assets/vision_test/secret1.jpg', out / 'resources')
        if result['resources']['passed'] is not True:
            raise ValueError('required resource gates did not pass; capacity not launched')
        for row in profiles:
            validate_binding(binding)
            code = capacity.run(row['protocol'], out / row['name'])
            result['profiles'].append({'name': row['name'], 'passed': code == 0})
            if code:
                raise ValueError('first failed capacity profile: ' + row['name'])
        result['passed'] = True
        # This campaign proves capacity only. Numerical/consumer/release gates
        # remain independent, including activation of a new public limit.
        result['capacity_qualified'] = True
    except Exception as error:
        result['error'] = f'{type(error).__name__}: {error}'
    finally:
        write(out / 'report.json', result)
    return result


def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='mode', required=True)
    for mode in ('proxy', 'prepare', 'bind', 'run-capacity'):
        cmd = sub.add_parser(mode)
        cmd.add_argument('--out', type=Path, required=True)
        if mode == 'bind':
            cmd.add_argument('--handoff', type=Path, required=True)
            cmd.add_argument('--binary', type=Path, required=True)
            cmd.add_argument('--model', type=Path, required=True)
        if mode == 'run-capacity':
            cmd.add_argument('--binding', type=Path, required=True)
            cmd.add_argument('--execute-on-target', action='store_true')
    a = p.parse_args()
    try:
        if a.mode == 'proxy': result = proxy(a.out)
        elif a.mode == 'prepare': result = prepare(a.out)
        elif a.mode == 'bind': result = bind(json.loads(a.handoff.read_text()), a.binary, a.model, a.out)
        else: result = run_capacity(json.loads(a.binding.read_text()), a.out, execute_on_target=a.execute_on_target)
        print(json.dumps({key: result[key] for key in ('kind', 'passed', 'state', 'error', 'hardware_qualified', 'release_qualified') if key in result}))
        return 0 if result.get('passed', True) else 1
    except Exception as error:
        print(json.dumps({'passed': False, 'error': f'{type(error).__name__}: {error}'}))
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

### Tools/context_resource_gates.py
#!/usr/bin/env python3
"""Bounded target-machine resource gates preceding the context capacity ladder."""
import json
import os
from pathlib import Path
import time

from context_qualification import quiet_preflight
from prefill_bench import digest, run_child, vm_snapshot
from memory_gate import swap_deltas


def validate_receipt(name, text, exit_code):
    if exit_code != 0 or 'SKIP' in text:
        raise ValueError('required resource diagnostic did not complete')
    prefix = 'ELASTIC DRILL MEMORY ' if name == 'governor' else 'MTP CHECK MEMORY '
    receipts = [json.loads(line[len(prefix):]) for line in text.splitlines() if line.startswith(prefix)]
    if len(receipts) != 1:
        raise ValueError('missing unique structured resource receipt')
    r = receipts[0]
    if name == 'governor':
        ids = r.get('output_ids')
        if ('ELASTIC DRILL PASS:' not in text or r.get('complete') is not True
                or r.get('ceiling_gb') != 13 or type(r.get('target_gb')) not in (int, float)
                or not 0 < r['target_gb'] <= 13 or not isinstance(ids, list) or len(ids) < 3
                or any(not isinstance(row, list) or not row or row != ids[0]
                       or any(type(token) is not int or not 0 <= token < 248320 for token in row) for row in ids)):
            raise ValueError('governor completion or resize equality failed')
        limit = 13
    elif name == 'mtp-vision':
        if ('MTP CHECK PASS' not in text or r.get('memory_validated') is not True or r.get('target_gb') != 12
                or 'PASS  vision speculation deterministic' not in text or 'PASS  vision speculation ran' not in text):
            raise ValueError('required MTP/vision path did not complete')
        limit = 12
    else:
        raise ValueError('unknown resource gate')
    for key in ('samples', 'sampled_peak_bytes', 'physical_footprint_end_bytes', 'lifetime_rss_peak_bytes'):
        if type(r.get(key)) is not int or r[key] <= 0:
            raise ValueError('invalid physical memory observation: ' + key)
    lifetime = r.get('lifetime_physical_footprint_peak_bytes')
    if lifetime is not None and (type(lifetime) is not int or lifetime <= 0):
        raise ValueError('invalid lifetime physical-footprint peak')
    if max(lifetime or 0, *(r[k] for k in ('sampled_peak_bytes', 'physical_footprint_end_bytes', 'lifetime_rss_peak_bytes'))) > limit * 1e9:
        raise ValueError('physical memory exceeded the fixed resource ceiling')
    if all(r.get(key + boundary) is not None for key in ('swapins', 'swapouts') for boundary in ('_before', '_after')):
        swap_deltas({key: r[key + '_before'] for key in ('swapins', 'swapouts')},
                    {key: r[key + '_after'] for key in ('swapins', 'swapouts')})
    return r


def run(binary, model, image, out):
    out.mkdir(parents=True, exist_ok=False)
    env = {k: v for k, v in os.environ.items() if not k.startswith('SLOTSTREAM_')}
    result = {'passed': False, 'kind': 'context-native-resource', 'cases': []}
    steps = [
        ('governor', ['elastic-drill', '--slots', '1000', '--max-memory-gb', '13'], 16, 600),
        ('mtp-vision', ['mtp-check', '--memory-gb', '12', '--mtp', 'on', '--vision', 'on', '--image', str(image)], 15, 900),
    ]
    for name, args, need, timeout in steps:
        cell = out / name
        cell.mkdir()
        row = {'name': name, 'passed': False, 'command': [str(binary), *args, '--model', str(model)]}
        result['cases'].append(row)
        try:
            row['before'] = quiet_preflight(need)
            row['exit_code'] = run_child(row['command'], env, cell, timeout)
            text = (cell / 'stdout.txt').read_text() + (cell / 'stderr.txt').read_text()
            row['receipt'] = validate_receipt(name, text, row['exit_code'])
            row['after'] = vm_snapshot()
            row['global_swap_deltas'] = swap_deltas(row['before'], row['after'])
            row['passed'] = True
        except Exception as error:
            row['error'] = f'{type(error).__name__}: {error}'
        finally:
            for name in ('stdout.txt', 'stderr.txt'):
                if (cell / name).exists():
                    row[name + '_sha256'] = digest(cell / name)
            (cell / 'manifest.json').write_text(json.dumps(row, indent=2) + '\n')
            result['passed'] = all(row['passed'] for row in result['cases']) and len(result['cases']) == len(steps)
            (out / 'manifest.json').write_text(json.dumps(result, indent=2) + '\n')
        if not row['passed']:
            break
    return result

