#!/usr/bin/env python3
"""Fresh trace screen for the floor-only layer-local replacement hypothesis.

No cache policy is enabled in inference. Replayed CLOCK must first reproduce
the real process's exact physical decode-record count, including prefill warmth.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import struct
from cache_policy_probe import Cache, RECORD_BYTES
from prefill_bench import preflight, run_child, model_identity, digest
from serve_bench import verified_build

PROMPTS = {
    'compiler': 'Write a detailed explanation of how a compiler detects syntax errors and reports line numbers.',
    'containers': 'Explain how a queue differs from a stack. Illustrate both with a short sequence of insertions and removals.',
}


def parse_trace(raw):
    if len(raw) > 1_000_000:
        raise ValueError('trace exceeds the fixed bounded request')
    calls = []
    offset = 0
    while offset < len(raw):
        if len(raw) - offset < 12:
            raise ValueError('incomplete trace header')
        layer, tokens, top_k = struct.unpack_from('<iii', raw, offset)
        offset += 12
        if layer != len(calls) % 48 or not 1 <= tokens <= 256 or top_k != 10:
            raise ValueError('unexpected layer or routing shape')
        count = tokens * top_k
        if len(raw) - offset < count * 2:
            raise ValueError('incomplete trace payload')
        ids = struct.unpack_from('<' + 'h' * count, raw, offset)
        offset += count * 2
        if min(ids) < 0 or max(ids) >= 512:
            raise ValueError('invalid expert ID')
        calls.append((layer, tokens, ids))
    if len(calls) < 96 or len(calls) % 48 or any(tokens != 1 for _, tokens, _ in calls[48:]):
        raise ValueError('expected one bounded prefill followed by complete decode passes')
    return calls


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--binary', type=Path, required=True)
    parser.add_argument('--model', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    a = parser.parse_args()
    build = verified_build(a.binary)
    a.out = a.out.resolve()
    a.out.mkdir(exist_ok=False, parents=True)
    sources = [Path(__file__), Path(__file__).with_name('cache_policy_probe.py'),
               Path(__file__).with_name('prefill_bench.py'), Path(__file__).with_name('serve_bench.py')]
    manifest = {'classification': 'fresh reference routing and offline floor-only cache hypothesis; not latency evidence',
                'build': build, 'model': model_identity(a.model.resolve()), 'prompts': PROMPTS,
                'slots': 640, 'memory_gb': 8.1, 'max_output_tokens': 64,
                'proposal': 'At exactly 640 slots, prefer empty then unpinned current-layer records; use CLOCK at every other capacity. No frequency counters or future routing inputs.',
                'gate': 'Both fresh prompts must produce at least sixteen decode passes, exact reference replay record counts and at least five percent fewer candidate physical decode records. No replacements or policy changes.'}
    manifest['sources'] = {p.name: digest(p) for p in sources}
    for source in sources:
        (a.out/source.name).write_bytes(source.read_bytes())
    (a.out/'manifest.json').write_text(json.dumps(manifest, indent=2)+'\n')
    rows = []
    for name, prompt in PROMPTS.items():
        cell = a.out/name
        cell.mkdir()
        (cell/'prompt.txt').write_text(prompt+'\n')
        command = [build['binary'], 'run', '--model', str(a.model.resolve()), '--memory-gb', '8.1',
                   '--mtp', 'off', '--prompt-file', str(cell/'prompt.txt'), '--greedy', '--seed', '7',
                   '--max-tokens', '64', '--stats-json', str(cell/'stats.json'), '--sample-footprint']
        env = {k: v for k, v in os.environ.items() if not k.startswith(('SLOTSTREAM_', 'SS_DEBUG'))}
        env |= {'SLOTSTREAM_ROUTER_TRACE': str(cell/'trace.bin'), 'SLOTSTREAM_PREFILL_CHUNK': '256',
                'SLOTSTREAM_PREFIX_CACHE': '0', 'SLOTSTREAM_OPT_COMPACT_STATE': '1', 'SLOTSTREAM_OPT_FINAL_FORWARD': '1'}
        row = {'name': name, 'command': command, 'environment': {k: v for k, v in env.items() if k.startswith('SLOTSTREAM_')}}
        row['preflight'] = preflight(11.1)
        row['exit_code'] = run_child(command, env, cell, 180)
        if row['exit_code']:
            (cell/'result.json').write_text(json.dumps(row, indent=2)+'\n')
            raise RuntimeError('reference trace generation failed')
        payload = json.loads((cell/'stats.json').read_text())
        calls = parse_trace((cell/'trace.bin').read_bytes())
        row['trace_sha256'] = digest(cell/'trace.bin')
        row['decode_passes'] = len(calls) // 48 - 1
        row['model_decode_records'] = payload['stats']['decodeRecords']
        for arm in ['reference', 'candidate']:
            cache = Cache(640, False, layer_local=arm == 'candidate')
            records = [cache.request(layer, ids) for layer, _, ids in calls]
            row[arm] = {'prefill_records': sum(records[:48]), 'decode_records': sum(records[48:]),
                        'by_call': records}
        row['reference_exact'] = row['reference']['decode_records'] == row['model_decode_records']
        row['record_reduction'] = 1 - row['candidate']['decode_records'] / row['reference']['decode_records']
        row['passed'] = row['decode_passes'] >= 16 and row['reference_exact'] and row['record_reduction'] >= .05
        (cell/'result.json').write_text(json.dumps(row, indent=2)+'\n')
        rows.append(row)
        print({k: row[k] for k in ['name', 'decode_passes', 'model_decode_records', 'reference_exact', 'record_reduction', 'passed']}, flush=True)
    passed = all(row['passed'] for row in rows)
    (a.out/'completion.json').write_text(json.dumps({'passed': passed, 'cells': len(rows)})+'\n')
    return 0 if passed else 1


if __name__ == '__main__':
    raise SystemExit(main())

### Tools/cachesim.py
"""M1: expert slot-cache simulator.

Replays real router traces against cache policies and sizes to produce the
h(size) curves the whole tiering rests on. No model needed.

Key modelling detail: the cache is GLOBAL across layers, keyed by
(layer, expert) -> 24,576 distinct records of 2.7648 MB each.

Usage:
  python cachesim.py bench/traces/*.npz
"""
import sys, json, glob
import numpy as np
from collections import OrderedDict, defaultdict

REC_MB = 2.7648
N_LAYERS, N_EXPERTS = 48, 512
TOTAL_RECORDS = N_LAYERS * N_EXPERTS


class LRU:
    name = "LRU"

    def __init__(self, cap):
        self.cap = cap
        self.d = OrderedDict()

    def access(self, key):
        if key in self.d:
            self.d.move_to_end(key)
            return True
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)
        self.d[key] = 1
        return False


class LFUDecay:
    """CLOCK-ish frequency cache: evict lowest freq, halve counters periodically."""
    name = "LFU-decay"

    def __init__(self, cap, decay_every=20000):
        self.cap = cap
        self.freq = {}
        self.n = 0
        self.decay_every = decay_every

    def access(self, key):
        self.n += 1
        if self.n % self.decay_every == 0:
            for k in self.freq:
                self.freq[k] >>= 1
        if key in self.freq:
            self.freq[key] += 1
            return True
        if len(self.freq) >= self.cap:
            victim = min(self.freq, key=self.freq.get)
            del self.freq[victim]
        self.freq[key] = 1
        return False


class Belady:
    """Offline optimal (upper bound). Only for small traces."""
    name = "OPT(bound)"

    def __init__(self, cap, seq):
        self.cap = cap
        self.next = defaultdict(list)
        for i, k in enumerate(seq):
            self.next[k].append(i)
        self.pos = defaultdict(int)
        self.cache = set()
        self.i = -1
        self.seq = seq

    def access(self, key):
        self.i += 1
        self.pos[key] += 1
        if key in self.cache:
            return True
        if len(self.cache) >= self.cap:
            # evict the one used farthest in the future
            worst, worst_at = None, -1
            for c in self.cache:
                nxt = self.next[c]
                p = self.pos[c]
                at = nxt[p] if p < len(nxt) else 10**9
                if at > worst_at:
                    worst, worst_at = c, at
            self.cache.discard(worst)
        self.cache.add(key)
        return False


def trace_to_keys(arr):
    """(steps, layers, topk) -> flat sequence of (layer*512+expert) keys."""
    steps, layers, topk = arr.shape
    lay = np.arange(layers, dtype=np.int32)[None, :, None]
    keys = lay * N_EXPERTS + arr.astype(np.int32)
    return keys.reshape(-1)


def hot_set_pinned(keys, cap, hot_frac=0.5):
    """Pin the globally hottest `hot_frac*cap` records, LRU the rest."""
    counts = np.bincount(keys, minlength=TOTAL_RECORDS)
    n_hot = int(cap * hot_frac)
    hot = set(np.argsort(-counts)[:n_hot].tolist())
    lru = LRU(cap - n_hot)
    hits = 0
    for k in keys:
        if k in hot:
            hits += 1
        elif lru.access(k):
            hits += 1
    return hits / len(keys)


def simulate(keys, cap, policy_cls):
    p = policy_cls(cap)
    hits = 0
    for k in keys:
        if p.access(int(k)):
            hits += 1
    return hits / len(keys)


def analyze(name, arr, caps_gb):
    keys = trace_to_keys(arr)
    steps = arr.shape[0]
    uniq = len(np.unique(keys))
    counts = np.bincount(keys, minlength=TOTAL_RECORDS)
    nz = counts[counts > 0]
    top10 = np.sort(counts)[::-1][: int(TOTAL_RECORDS * 0.1)].sum() / counts.sum()

    print(f"\n### {name}: {steps} steps, {len(keys):,} expert-uses")
    print(f"    distinct records touched: {uniq:,} / {TOTAL_RECORDS:,} "
          f"({100*uniq/TOTAL_RECORDS:.1f}%)")
    print(f"    top-10% of records serve {100*top10:.1f}% of accesses "
          f"(concentration)")
    print(f"    working set if fully cached: {uniq*REC_MB/1024:.1f} GB")

    print(f"    {'exp/layer':>9} {'cache GB':>9} {'slots':>7} {'LRU':>8} {'LFU':>8} {'hot+LRU':>8}"
          f" {'miss MB/tok':>12} {'IO ms/tok@6GB/s':>16}")
    rows = []
    for gb in caps_gb:
        cap = int(gb * 1024 / REC_MB)
        if cap < 1:
            continue
        h_lru = simulate(keys, cap, LRU)
        h_lfu = simulate(keys, cap, LFUDecay)
        h_hot = hot_set_pinned(keys, cap)
        best = max(h_lru, h_lfu, h_hot)
        per_tok = arr.shape[1] * arr.shape[2]  # layers*topk expert-uses per token
        miss_mb = per_tok * (1 - best) * REC_MB
        io_ms = miss_mb / 6000 * 1000
        print(f"    {cap/N_LAYERS:9.1f} {gb:9.1f} {cap:7d} {h_lru:8.3f} {h_lfu:8.3f} {h_hot:8.3f}"
              f" {miss_mb:12.1f} {io_ms:16.1f}")
        rows.append(dict(gb=gb, slots=cap, lru=h_lru, lfu=h_lfu, hot=h_hot,
                         miss_mb=miss_mb, io_ms=io_ms))
    return rows


if __name__ == "__main__":
    files = sys.argv[1:] or sorted(glob.glob("bench/traces/*.npz"))
    if not files:
        print("no traces given"); sys.exit(1)
    caps = [0.5, 1, 2, 5.5, 10.5, 16, 27, 36, 56, 68]
    out = {}
    for f in files:
        z = np.load(f)
        for k in z.files:
            if k == "meta":
                continue
            arr = z[k]
            if arr.ndim != 3:
                continue
            out[f"{f}:{k}"] = analyze(f"{f.split('/')[-1]}:{k}", arr, caps)
    with open("bench/locality/summary.json", "w") as fh:
        json.dump(out, fh, indent=2)
    print("\nwrote bench/locality/summary.json")

### Tools/claims_gate.py
#!/usr/bin/env python3
"""Every public number has a claim record; every claim's needle is on its surfaces.

Reads db/records/claims/*.md. A `current` claim's `needle` must appear
verbatim in every file listed in `surfaces`; a `withdrawn` claim's needle
must appear in none of them. The gate exists because numbers drifted between
README, docs, and llms.txt for three releases before anyone noticed; a
measurement that changes now fails CI until its claim and its surfaces move
together. Matching ignores line wrapping: runs of whitespace on both sides
collapse to one space, so a needle may span a wrapped line. Standard library
only.
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLAIMS = os.path.join(ROOT, 'db', 'records', 'claims')

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from projections import read_record  # noqa: E402


def squash(text):
    return ' '.join(text.split())


def main():
    if not os.path.isdir(CLAIMS):
        print('no claims folder at %s' % CLAIMS, file=sys.stderr)
        return 1
    failures, checked = [], 0
    for name in sorted(os.listdir(CLAIMS)):
        if not name.endswith('.md') or name == 'index.md':
            continue
        fm, _ = read_record(os.path.join(CLAIMS, name))
        needle = fm.get('needle', '')
        status = fm.get('status', '')
        surfaces = [s.strip() for s in fm.get('surfaces', '').split(',') if s.strip()]
        if not needle or not surfaces or status not in ('current', 'withdrawn'):
            failures.append('%s: needs needle, surfaces, and a current/withdrawn status' % name)
            continue
        for surface in surfaces:
            path = os.path.join(ROOT, surface)
            if not os.path.isfile(path):
                failures.append('%s: surface %s does not exist' % (name, surface))
                continue
            present = squash(needle) in squash(open(path, encoding='utf-8').read())
            checked += 1
            if status == 'current' and not present:
                failures.append('%s: current claim needle %r missing from %s' % (name, needle, surface))
            if status == 'withdrawn' and present:
                failures.append('%s: withdrawn claim needle %r still on %s' % (name, needle, surface))
    for f in failures:
        print('CLAIM FAIL ' + f, file=sys.stderr)
    print('claims gate: %d needle checks, %d failures' % (checked, len(failures)))
    return 1 if failures else 0


if __name__ == '__main__':
    sys.exit(main())

