    out = args.out.resolve(); out.mkdir(parents=True, exist_ok=False)
    env = {k: v for k, v in os.environ.items() if not k.startswith(('SLOTSTREAM_', 'SS_DEBUG'))}
    previous = args.previous.resolve()
    shutil.copy2(previous/'outputs/ssv_long.txt', out/'long-prompt.txt')
    sources = ['verify_corrections.py', 'verify.sh', 'api_robustness.sh', 'memory_gate.py',
               'long_context_gate.py', 'prefill_bench.py', 'serve_bench.py']
    record = {'classification': 'Targeted delivery correction of full V68, not a speed comparison',
        'build': build, 'previous': str(previous), 'memory_gb': 10,
        'required_reclaimable_gb': 13, 'experimental_controls': 'all default off',
        'long_prompt_sha256': digest(out/'long-prompt.txt'),
        'contract': 'Short and long requests explicitly sample physical footprint and retain the 10 GB process ceiling. Global macOS paging is diagnostic under the current functional-acceptance policy; historical V68 verdicts stay unchanged. The unchanged long source is passed through the normal non-thinking chat template, with the same 16-token allowance; require a completed standalone recalled value and at least 7000 prompt tokens. Repair Bash 3.2 empty optional arguments; run the complete API robustness script. Do not rerun passing V68 gates. No replacement or relaxed process-memory ceiling.',
        'source_hashes': {}, 'results': [], 'completed': False}
    for name in sources:
        path = ROOT/'Tools'/name; record['source_hashes'][name] = digest(path)
        shutil.copy2(path, out/name)
    (out/'protocol.json').write_text(json.dumps(record, indent=2)+'\n')
    try:
        for name in ['short-memory', 'long-memory-and-recall', 'api']:
            cell = out/name; cell.mkdir()
            result = {'name': name, 'before': preflight(13), 'gates': {}}
            child_env = env.copy()
            if name == 'api':
                with socket.socket() as reservation:
                    reservation.bind(('127.0.0.1', 0)); port = reservation.getsockname()[1]
                child_env.update({'SLOTSTREAM_TEST_BINARY': build['binary'], 'SLOTSTREAM_TEST_LOG': str(cell/'server.log')})
                command = ['/bin/bash', str(ROOT/'Tools/api_robustness.sh'), str(port), '13']
            else:
                command = [build['binary'], 'run', '--memory-gb', '10', '--mtp', 'off', '--greedy',
                           '--sample-footprint', '--stats-json', str(cell/'stats.json')]
                command += ['--prompt-file', str(out/'long-prompt.txt'), '--max-tokens', '16'] if name.startswith('long') else [
                    '--prompt', 'Why is the sky blue?', '--max-tokens', '24']
            result['command'] = command
            print(json.dumps({'started': name}), flush=True)
            result['exit_code'] = run_child(command, child_env, cell, 900)
            if name == 'api': result['gates']['api'] = {'passed': result['exit_code'] == 0}
            elif result['exit_code'] == 0:
                payload = json.loads((cell/'stats.json').read_text())
                try: result['gates']['memory'] = check_memory(payload, 10)
                except (ValueError, KeyError, TypeError) as error:
                    result['gates']['memory'] = {'passed': False, 'error': str(error)}
                if name.startswith('long'):
                    try: result['gates']['recall'] = check_answer(payload, (cell/'stdout.txt').read_text(), 'SEVENTEEN', 7000, 16)
                    except (ValueError, KeyError, TypeError) as error:
                        result['gates']['recall'] = {'passed': False, 'error': str(error)}
            result['after'] = vm_snapshot()
            result['passed'] = result['exit_code'] == 0 and bool(result['gates']) and all(g['passed'] for g in result['gates'].values())
            (cell/'result.json').write_text(json.dumps(result, indent=2)+'\n')
            record['results'].append(result)
            print(json.dumps({'finished': name, 'gates': result['gates'], 'passed': result['passed']}), flush=True)
        record['completed'] = True
    finally:
        record['sources_unchanged'] = all(digest(ROOT/'Tools'/n) == v for n, v in record['source_hashes'].items())
        record['passed'] = record['completed'] and record['sources_unchanged'] and all(r['passed'] for r in record['results'])
        (out/'manifest.json').write_text(json.dumps(record, indent=2)+'\n')
    return 0 if record['passed'] else 1


if __name__ == '__main__':
    raise SystemExit(main())

### Tools/vision_attention_probe.py
#!/usr/bin/env python3
"""Bounded 72-wide vision attention padding experiment, pinned MLX 0.31.1.
Fixed-input evidence only; full-tower, task quality and request gates are separate.
"""
import hashlib
import importlib.metadata
import json
from pathlib import Path
import statistics
import time
import mlx.core as mx
import numpy as np
from prefill_bench import preflight, vm_snapshot


def attention(q, k, v, padded):
    original = q.shape[-1]
    if padded:
        widths = [(0, 0)] * (q.ndim - 1) + [(0, padded - original)]
        q, k, v = [mx.pad(x, widths) for x in [q, k, v]]
    out = mx.fast.scaled_dot_product_attention(q, k, v, scale=original ** -.5)
    return out[..., :original]


def main():
    version = importlib.metadata.version('mlx')
    if version != '0.31.1': raise ValueError('probe requires pinned MLX 0.31.1')
    record = {'classification': 'fixed-input numerical and exploratory component performance only',
              'mlx': version, 'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              'before': preflight(7), 'checks': [], 'timings': [],
              'contract': 'CPU float64 softmax oracle. Float32 max error <=max(3*unpadded error,1e-5); BF16 <=max(3*unpadded error,0.01). Every output finite. Scale remains 1/sqrt(72). Five AB/BA rounds per shape, five completed calls per arm; any global swap excludes the whole round. No inference adoption.'}
    mx.set_cache_limit(128 << 20)
    rng = np.random.default_rng(17029)
    for n in [1, 8, 9, 64, 256]:
        for dtype in [mx.float32, mx.bfloat16]:
            for kind in ['random', 'zero-query', 'saturated']:
                raw = [rng.standard_normal((1, 2, n, 72)).astype(np.float32) for _ in range(3)]
                if kind == 'zero-query': raw[0].fill(0)
                if kind == 'saturated': raw[0] *= 32; raw[1] *= 32
                arrays = [mx.array(x).astype(dtype) for x in raw]; mx.eval(arrays)
                q, k, v = [np.array(x.astype(mx.float32)).astype(np.float64) for x in arrays]
                scores = (q @ k.swapaxes(-1, -2)) / np.sqrt(72)
                probs = np.exp(scores - scores.max(axis=-1, keepdims=True)); probs /= probs.sum(axis=-1, keepdims=True)
                oracle = probs @ v
                baseline = np.array(attention(*arrays, 0).astype(mx.float32))
                error = float(np.max(np.abs(baseline - oracle)))
                for padded in [80, 128]:
                    out = np.array(attention(*arrays, padded).astype(mx.float32))
                    changed = float(np.max(np.abs(out - oracle)))
                    limit = max(3 * error, 1e-5 if dtype == mx.float32 else .01)
                    record['checks'].append({'n': n, 'dtype': str(dtype), 'kind': kind, 'padding': padded,
                        'reference_max_error': error, 'candidate_max_error': changed, 'limit': limit,
                        'passed': bool(np.isfinite(out).all() and changed <= limit)})
    for n in [256, 1024, 2048]:
        arrays = [mx.array(rng.standard_normal((1, 16, n, 72)).astype(np.float32)).astype(mx.bfloat16) for _ in range(3)]
        mx.eval(arrays)
        for p in [0, 80, 128]:
            for _ in range(2): mx.eval(attention(*arrays, p))
        rounds = []
        for r in range(5):
            cells = []
            for p in ([0, 80, 128] if r % 2 == 0 else [128, 80, 0]):
                before = vm_snapshot(); mx.reset_peak_memory(); start = time.monotonic()
                for _ in range(5): mx.eval(attention(*arrays, p))
                elapsed = (time.monotonic() - start) / 5
                after = vm_snapshot()
                cells.append({'padding': p, 'seconds': elapsed,
                              'mlx_peak_bytes': max(mx.get_peak_memory(), mx.get_active_memory()),
                              'swap_delta': {k: after[k] - before[k] for k in ['swapins', 'swapouts']}})
            rounds.append({'round': r + 1, 'cells': cells,
                'valid': all(not any(c['swap_delta'].values()) for c in cells)})
        record['timings'].append({'n': n, 'heads': 16, 'rounds': rounds})
    record['passed'] = all(c['passed'] for c in record['checks'])
    record['after'] = vm_snapshot()
    print(json.dumps(record, indent=2))
    return 0 if record['passed'] else 1


if __name__ == '__main__': raise SystemExit(main())

